import { company } from "@/data/company";

export const siteUrl = company.siteUrl;

export function absoluteUrl(path = "/") {
  return new URL(path, `${siteUrl}/`).toString();
}

/**
 * Build per-page metadata with a canonical URL, Open Graph and Twitter card.
 * Titles are passed in full (no template) so each page controls its exact title.
 */
/** Site-wide social image generated by src/app/opengraph-image.js. */
export const socialImage = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: `${company.brandName}: ${company.tagline}`,
};

export function buildMetadata({ title, description, path = "/" }) {
  return {
    title: { absolute: title },
    description,
    alternates: { canonical: path },
    openGraph: {
      type: "website",
      locale: "en_GH",
      siteName: company.brandName,
      url: path,
      title,
      description,
      images: [socialImage],
    },
    twitter: {
      card: "summary_large_image",
      title,
      description,
      images: [socialImage.url],
    },
  };
}

/* ---------------------------- JSON-LD builders ---------------------------- */

const orgId = `${siteUrl}/#organization`;
const websiteId = `${siteUrl}/#website`;

export function organizationSchema() {
  const schema = {
    "@context": "https://schema.org",
    "@type": "Organization",
    "@id": orgId,
    name: company.brandName,
    legalName: company.legalName,
    alternateName: company.shortName,
    url: `${siteUrl}/`,
    description: company.description,
    slogan: company.tagline,
    areaServed: { "@type": "Country", name: company.country },
    knowsAbout: [
      "Software development",
      "Custom software development",
      "Web application development",
      "Institutional software",
      "Student information systems",
      "Clinical practical assessment software",
      "Academic document request systems",
      "Website design and development",
      "Systems integration",
      "Business process automation",
    ],
  };
  if (company.logoSquare || company.logo) schema.logo = absoluteUrl(company.logoSquare || company.logo);
  if (company.contact.email) schema.email = company.contact.email;
  if (company.contact.phone) schema.telephone = company.contact.phone;
  if (company.social.length) schema.sameAs = company.social.map((s) => s.href);
  return schema;
}

export function websiteSchema() {
  return {
    "@context": "https://schema.org",
    "@type": "WebSite",
    "@id": websiteId,
    url: `${siteUrl}/`,
    name: company.brandName,
    description: company.description,
    inLanguage: "en",
    publisher: { "@id": orgId },
  };
}

/** items: [{ name, path }] — Home is prepended automatically. */
export function breadcrumbSchema(items) {
  const all = [{ name: "Home", path: "/" }, ...items];
  return {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    itemListElement: all.map((item, index) => ({
      "@type": "ListItem",
      position: index + 1,
      name: item.name,
      item: absoluteUrl(item.path),
    })),
  };
}

export function servicesSchema(services) {
  return {
    "@context": "https://schema.org",
    "@type": "ItemList",
    name: `Services from ${company.brandName}`,
    itemListElement: services.map((service, index) => ({
      "@type": "ListItem",
      position: index + 1,
      item: {
        "@type": "Service",
        "@id": absoluteUrl(`/services#${service.slug}`),
        name: service.title,
        serviceType: service.title,
        description: service.summary,
        url: absoluteUrl(`/services#${service.slug}`),
        provider: { "@id": orgId },
        areaServed: { "@type": "Country", name: company.country },
      },
    })),
  };
}
